from kings import ISRAEL,JUDAH
AUD={'北国':'#ff6b6b','南国':'#5cc8ff','外邦':'#ff9f43','被掳':'#b78cff','归回':'#2dd4bf','—':'#9aa3c7'}
# (name, start, end, audience, kings, empire, id)
PR=[('以利亚*',875,848,'北国','亚哈、亚哈谢','—',None),('以利沙*',848,797,'北国','约兰—约阿施','亚兰',None),('约珥',835,830,'南国','约阿施？（年代不详）','—','joe'),('约拿',785,760,'外邦','耶罗波安二世（王下14:25）','亚述','jon'),('阿摩司',762,755,'北国','乌西雅、耶罗波安二世（1:1）','亚述','amo'),('何西阿',755,715,'北国','乌西雅—希西家；耶罗波安二世（1:1）','亚述','hos'),('以赛亚',740,681,'南国','乌西雅、约坦、亚哈斯、希西家（1:1）','亚述','isa'),('弥迦',735,700,'南国','约坦、亚哈斯、希西家（1:1）','亚述','mic'),('那鸿',660,650,'外邦','玛拿西','亚述','nah'),('西番雅',635,625,'南国','约西亚（1:1）','亚述→巴比伦','zep'),('耶利米',627,580,'南国','约西亚—西底家（1:1–3）','巴比伦','jer'),('哈巴谷',609,605,'南国','约雅敬','巴比伦','hab'),('但以理',605,536,'被掳','尼布甲尼撒—古列','巴比伦→波斯','dan'),('以西结',593,571,'被掳','约雅斤被掳第5年起（1:2）','巴比伦','eze'),('耶利米哀歌',586,585,'南国','西底家之后','巴比伦','lam'),('俄巴底亚',586,580,'外邦','耶路撒冷陷落后（另说约845）','巴比伦','oba'),('哈该',520,520,'归回','大利乌一世第2年（1:1）','波斯','hag'),('撒迦利亚',520,480,'归回','大利乌一世','波斯','zec'),('玛拉基',433,420,'归回','亚达薛西一世（尼希米时期）','波斯','mal')]
def pchart():
    y0,y1=-885,-415; W=1180; lw=110; X=lambda y:lw+(y-y0)/(y1-y0)*(W-lw-16)
    rh=26; top=60; s=[]
    lanes=[('帝国',36),('以色列',top+4),('犹大',top+34)]
    pT=top+74; H=pT+len(PR)*rh+34
    s.append(f'<svg viewBox="0 0 {W} {H}" role="img" aria-label="先知 × 君王 × 帝国 时间轴">')
    for t in range(-875,-414,25):
        if t%50==0 or t==-875: s.append(f'<line x1="{X(t):.1f}" x2="{X(t):.1f}" y1="20" y2="{H-24}" class="gl"/><text x="{X(t):.1f}" y="{H-8}" text-anchor="middle" class="ax">{-t}</text>')
    for lb,a,b,col in [('亚述',-885,-612,'#ff9f43'),('巴比伦',-612,-539,'#b78cff'),('波斯',-539,-415,'#2dd4bf')]:
        s.append(f'<rect x="{X(a):.1f}" y="18" width="{X(b)-X(a):.1f}" height="24" rx="6" fill="{col}" opacity=".85"/><text x="{(X(a)+X(b))/2:.1f}" y="35" text-anchor="middle" class="pe">{lb}</text>')
    for yr,lb in [(-722,'722 北亡'),(-586,'586 南亡'),(-538,'538 归回'),(-516,'516 殿成')]:
        s.append(f'<line x1="{X(yr):.1f}" x2="{X(yr):.1f}" y1="44" y2="{H-24}" class="pev"/><text x="{X(yr)+3:.1f}" y="{H-24}" class="pevt">{lb}</text>')
    s.append(f'<text x="{lw-8}" y="35" text-anchor="end" class="spl">帝国</text>')
    VC={'good':'#3ee0a1','evil':'#ff6b6b','mix':'#ffb34d'}
    for name,L,yy in (('以色列',ISRAEL,top+4),('犹大',JUDAH,top+34)):
        s.append(f'<text x="{lw-8}" y="{yy+17}" text-anchor="end" class="spl">{name}王</text>')
        for i,k in enumerate(L):
            a=k[2]; nx=L[i+1][2] if i+1<len(L) else k[3]; b=nx if nx<a else k[3]
            if b>=a: b=a-.6
            if -a>y1 or -b<y0: continue
            xa=max(X(-a),lw); xb=X(-b); w=max(xb-xa,1.5)
            s.append(f'<rect x="{xa:.1f}" y="{yy}" width="{w:.1f}" height="24" fill="{VC[k[5]]}" opacity=".78" stroke="var(--bg)" stroke-width="1"><title>{name} · {k[0]}（{k[2]}–{k[3]} BC）</title></rect>')
            if w>=30: s.append(f'<text x="{xa+w/2:.1f}" y="{yy+16}" text-anchor="middle" class="pk">{k[0][:3]}</text>')
    for i,(n,a,b,au,kg,emp,bid) in enumerate(PR):
        y=pT+i*rh; xa=X(-a); w=max(X(-b)-xa,7); col=AUD[au]
        s.append(f'<g class="spr" style="--d:{i*35}ms"><text x="{lw-8}" y="{y+16}" text-anchor="end" class="spl{" dim" if "*" in n else ""}">{n.rstrip("*")}</text><rect x="{xa:.1f}" y="{y+3}" width="{w:.1f}" height="{rh-7}" rx="5" fill="{col}"{" opacity=.55" if "*" in n else ""}><title>{n.rstrip("*")}：约 {a}–{b} BC · 对象：{au} · 同期：{kg}</title></rect><text x="{(xa+w+6) if a>470 else (xa-6):.1f}" y="{y+16}" class="spt2"{"" if a>470 else " text-anchor=end"}>{a}{"–"+str(b) if b!=a else ""} · {kg}</text></g>')
    s.append('</svg>')
    leg=''.join(f'<span style="--c:{c}"><i></i>{k}</span>' for k,c in AUD.items() if k!='—')+'<span style="--c:#3ee0a1"><i></i>善王</span><span style="--c:#ff6b6b"><i></i>恶王</span><span style="--c:#ffb34d"><i></i>参半</span>'
    return f'<figure class="v6c spanc pchart rv" id="pchart"><div class="v6sc">{"".join(s).replace("<svg ","<svg style=min-width:1000px ",1)}</div><div class="legend">{leg}</div><figcaption class="srcline">保守派年代（约略；约珥、俄巴底亚年代有争议）。*以利亚、以利沙为非写作先知，作参照。上两条＝南北诸王（独立在位期，颜色＝圣经评价）；顶部＝帝国；竖线＝四个钉子年份。悬停看细节；手机左右滑动。</figcaption></figure>'
def mountains():
    s='''<svg viewBox="0 0 900 300" role="img" aria-label="先知的透视：山峰重叠">
<defs><linearGradient id="mg1" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--gold)"/><stop offset="1" stop-color="var(--gold)" stop-opacity=".1"/></linearGradient><linearGradient id="mg2" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--rose)"/><stop offset="1" stop-color="var(--rose)" stop-opacity=".1"/></linearGradient><linearGradient id="mg3" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--sky)"/><stop offset="1" stop-color="var(--sky)" stop-opacity=".1"/></linearGradient></defs>
<polygon points="560,250 720,50 880,250" fill="url(#mg1)"/><polygon points="380,250 520,95 660,250" fill="url(#mg2)"/><polygon points="200,250 310,140 420,250" fill="url(#mg3)"/>
<text x="720" y="40" text-anchor="middle" class="tn">③ 基督再来 · 末日审判与新天新地</text><text x="520" y="85" text-anchor="middle" class="tn">② 基督第一次降临 · 五旬节</text><text x="310" y="130" text-anchor="middle" class="tn">① 近处的审判：722 / 586</text>
<line x1="20" y1="250" x2="880" y2="250" stroke="var(--line2)" stroke-width="2"/><text x="60" y="222" font-size="40">👁️</text><text x="40" y="280" class="tx">先知站在这里看：三座山像一座</text>
<path d="M95 205 L 700 70" stroke="var(--mut)" stroke-dasharray="5 6" fill="none"/></svg>'''
    return f'<figure class="vchart mnt tri rv">{s}<figcaption class="srcline">“先知的透视”（示意）：先知看“耶和华的日子”像远望群山——近的历史审判、基督第一次降临、基督再来<b class="k">叠在一起</b>。新约把它们分开：珥2:28–32 在五旬节应验（徒2:16–21），“日头变为黑暗”的完全应验仍在末日。</figcaption></figure>'
